//! op-openvswitch-daemon — D-Bus hypervisor for rovs crate family
//!
//! Pure pass-through proxy:
//! - /org/opdbus/rovs/jsonrpc  → OVSDB JSON-RPC (rovs-jsonrpc)
//! - /org/opdbus/rovs/openflow → OpenFlow (rovs-openflow)
//!
//! AGENTS.md §4: D-Bus first, D-Bus only. No CLI wrappers. No OvsdbClient.

use anyhow::{Context, Result};
use rovs_jsonrpc::Connection as JsonRpcConnection;
use rovs_openflow::VConn;
use rovs_transport::{Stream, reconnect::Reconnect};
use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::Arc;
use tokio::net::TcpListener;
use tokio::sync::{Mutex, RwLock};
use tracing::{info, warn, error};
use zbus::{connection, interface, Connection};

// ── Configuration ────────────────────────────────────────────────────────────

const SYSTEM_BUS_DEST: &str = "org.opdbus.v1";
const JSONRPC_PATH: &str = "/org/opdbus/rovs/jsonrpc";
const OPENFLOW_PATH: &str = "/org/opdbus/rovs/openflow";
const OVSDB_SOCKET: &str = "/run/openvswitch/db.sock";
const OF_CONTROLLER_PORT: u16 = 6653;

// ── JSON-RPC Interface ───────────────────────────────────────────────────────

/// org.opdbus.rovs.jsonrpc interface — pure OVSDB JSON-RPC passthrough
struct RovsJsonRpcInterface {
    conn: Arc<Mutex<JsonRpcConnection>>,
    notification_buffer: Arc<Mutex<Vec<String>>>,
}

#[interface(name = "org.opdbus.rovs.jsonrpc")]
impl RovsJsonRpcInterface {
    /// Execute a raw OVSDB JSON-RPC transact
    async fn transact(&self, method: &str, params_json: &str) -> zbus::Result<String> {
        let conn = self.conn.lock().await;
        let params: serde_json::Value = serde_json::from_str(params_json)
            .map_err(|e| zbus::Error::InvalidArgs(format!("invalid JSON: {}", e)))?;

        let result = conn.transact(method, params)
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("transact failed: {}", e)
            )))?;

        Ok(result.to_string())
    }

    /// Execute a one-way notify
    async fn notify(&self, method: &str, params_json: &str) -> zbus::Result<()> {
        let conn = self.conn.lock().await;
        let params: serde_json::Value = serde_json::from_str(params_json)
            .map_err(|e| zbus::Error::InvalidArgs(format!("invalid JSON: {}", e)))?;

        conn.notify(method, params)
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("notify failed: {}", e)
            )))?;

        Ok(())
    }

    /// Return next JSON-RPC request ID
    async fn next_id(&self) -> zbus::Result<u64> {
        let mut conn = self.conn.lock().await;
        Ok(conn.next_id())
    }

    /// Send raw message string, return response
    async fn send_message(&self, msg: &str) -> zbus::Result<String> {
        let conn = self.conn.lock().await;
        let msg_json: serde_json::Value = serde_json::from_str(msg)
            .map_err(|e| zbus::Error::InvalidArgs(format!("invalid JSON: {}", e)))?;

        let response = conn.send_message(&msg_json)
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("send failed: {}", e)
            )))?;

        Ok(response.to_string())
    }

    /// Receive raw JSON-RPC message
    async fn recv_message(&self) -> zbus::Result<String> {
        let mut conn = self.conn.lock().await;
        let msg = conn.recv_message()
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("recv failed: {}", e)
            )))?;

        Ok(msg.to_string())
    }

    /// Check if notifications pending
    async fn has_pending_notifications(&self) -> zbus::Result<bool> {
        let buffer = self.notification_buffer.lock().await;
        Ok(!buffer.is_empty())
    }

    /// Count pending notifications
    async fn pending_notification_count(&self) -> zbus::Result<u64> {
        let buffer = self.notification_buffer.lock().await;
        Ok(buffer.len() as u64)
    }

    /// Pop one notification
    async fn pop_notification(&self) -> zbus::Result<String> {
        let mut buffer = self.notification_buffer.lock().await;
        buffer.pop().ok_or_else(|| {
            zbus::Error::InvalidArgs("no pending notifications".to_string())
        })
    }

    /// Drain all notifications as JSON array
    async fn drain_notifications(&self) -> zbus::Result<String> {
        let mut buffer = self.notification_buffer.lock().await;
        let drained: Vec<String> = buffer.drain(..).collect();
        Ok(format!("[{}]", drained.join(",")))
    }

    /// Open a new named stream/monitor
    async fn new_stream(&self, stream: &str) -> zbus::Result<String> {
        let conn = self.conn.lock().await;
        let result = conn.new_stream(stream)
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("new_stream failed: {}", e)
            )))?;

        Ok(result.to_string())
    }

    /// Daemon status JSON
    async fn status(&self) -> zbus::Result<String> {
        let status = serde_json::json!({
            "service": "op-openvswitch-daemon",
            "version": env!("CARGO_PKG_VERSION"),
            "jsonrpc": "connected",
            "openflow": "listening",
        });
        Ok(status.to_string())
    }
}

// ── OpenFlow Interface ───────────────────────────────────────────────────────

/// org.opdbus.rovs.openflow interface — OpenFlow controller passthrough
struct RovsOpenFlowInterface {
    /// Active VConn connections by handle ID
    connections: Arc<RwLock<HashMap<String, Arc<Mutex<VConn>>>>>,
    /// Next connection ID
    next_id: Arc<Mutex<u64>>,
    /// Passive listen address
    listen_addr: SocketAddr,
}

#[interface(name = "org.opdbus.rovs.openflow")]
impl RovsOpenFlowInterface {
    /// Connect to a switch (active). Returns connection handle ID.
    async fn connect(&self, addr: &str) -> zbus::Result<String> {
        let stream = Stream::connect(addr)
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("connect failed: {}", e)
            )))?;

        let vconn = VConn::new(stream)
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("VConn handshake failed: {}", e)
            )))?;

        let id = self.allocate_id().await;
        let mut conns = self.connections.write().await;
        conns.insert(id.clone(), Arc::new(Mutex::new(vconn)));

        info!("OpenFlow: active connection {} established to {}", id, addr);
        Ok(id)
    }

    /// Return negotiated OpenFlow version JSON
    async fn version(&self, handle: &str) -> zbus::Result<String> {
        let conns = self.connections.read().await;
        let vconn = conns.get(handle)
            .ok_or_else(|| zbus::Error::InvalidArgs(format!("invalid handle: {}", handle)))?;

        let vconn = vconn.lock().await;
        let version = serde_json::json!({
            "version": format!("{:?}", vconn.version()),
            "handle": handle,
        });
        Ok(version.to_string())
    }

    /// Send a flow_mod (async)
    async fn send_flow(&self, handle: &str, flow_json: &str) -> zbus::Result<String> {
        let flow: rovs_openflow::Flow = serde_json::from_str(flow_json)
            .map_err(|e| zbus::Error::InvalidArgs(format!("invalid flow JSON: {}", e)))?;

        let conns = self.connections.read().await;
        let vconn = conns.get(handle)
            .ok_or_else(|| zbus::Error::InvalidArgs(format!("invalid handle: {}", handle)))?;

        let mut vconn = vconn.lock().await;
        vconn.send_flow(&flow)
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("send_flow failed: {}", e)
            )))?;

        Ok(format!("{{\"sent\":true,\"handle\":\"{}\"}}", handle))
    }

    /// Send flow_mod and wait for barrier
    async fn send_flow_sync(&self, handle: &str, flow_json: &str) -> zbus::Result<String> {
        self.send_flow(handle, flow_json).await?;
        self.barrier(handle).await
    }

    /// Send echo request, return echo reply
    async fn echo(&self, handle: &str) -> zbus::Result<String> {
        let conns = self.connections.read().await;
        let vconn = conns.get(handle)
            .ok_or_else(|| zbus::Error::InvalidArgs(format!("invalid handle: {}", handle)))?;

        let mut vconn = vconn.lock().await;
        let reply = vconn.echo()
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("echo failed: {}", e)
            )))?;

        Ok(serde_json::to_string(&reply)
            .unwrap_or_else(|_| "{}".to_string()))
    }

    /// Send barrier, wait for reply
    async fn barrier(&self, handle: &str) -> zbus::Result<String> {
        let conns = self.connections.read().await;
        let vconn = conns.get(handle)
            .ok_or_else(|| zbus::Error::InvalidArgs(format!("invalid handle: {}", handle)))?;

        let mut vconn = vconn.lock().await;
        vconn.barrier()
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("barrier failed: {}", e)
            )))?;

        Ok(format!("{{\"barrier\":true,\"handle\":\"{}\"}}", handle))
    }

    /// Dump all flows
    async fn dump_flows(&self, handle: &str) -> zbus::Result<Vec<String>> {
        let conns = self.connections.read().await;
        let vconn = conns.get(handle)
            .ok_or_else(|| zbus::Error::InvalidArgs(format!("invalid handle: {}", handle)))?;

        let mut vconn = vconn.lock().await;
        let flows = vconn.dump_flows()
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("dump_flows failed: {}", e)
            )))?;

        let json_flows: Vec<String> = flows.iter()
            .map(|f| serde_json::to_string(f).unwrap_or_default())
            .collect();
        Ok(json_flows)
    }

    /// Dump flows with filter
    async fn dump_flows_filtered(&self, handle: &str, request: &str) -> zbus::Result<Vec<String>> {
        // For now, delegate to dump_flows (filter applied client-side)
        // Full implementation would parse request and construct match
        self.dump_flows(handle).await
    }

    /// Block until PacketIn arrives
    async fn recv_packet_in(&self, handle: &str) -> zbus::Result<String> {
        let conns = self.connections.read().await;
        let vconn = conns.get(handle)
            .ok_or_else(|| zbus::Error::InvalidArgs(format!("invalid handle: {}", handle)))?;

        let mut vconn = vconn.lock().await;
        let packet = vconn.recv_packet_in()
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("recv_packet_in failed: {}", e)
            )))?;

        Ok(serde_json::to_string(&packet)
            .unwrap_or_else(|_| "{}".to_string()))
    }

    /// Non-blocking try-receive PacketIn
    async fn try_recv_packet_in(&self, handle: &str) -> zbus::Result<String> {
        // For now, use recv_packet_in with timeout = 0 (would need VConn support)
        // Return empty if no packet pending
        match self.recv_packet_in(handle).await {
            Ok(packet) => Ok(packet),
            Err(zbus::Error::Io(e)) if e.kind() == std::io::ErrorKind::WouldBlock => {
                Ok("{}".to_string())
            }
            Err(e) => Err(e),
        }
    }

    /// Start flow monitor
    async fn monitor_flows(&self, handle: &str, _request: &str) -> zbus::Result<Vec<String>> {
        // Placeholder: rovs-openflow doesn't expose monitor API directly
        // Full implementation would use async stream
        Ok(vec![])
    }

    /// Block until flow updates arrive
    async fn recv_flow_updates(&self, _handle: &str) -> zbus::Result<Vec<String>> {
        // Placeholder: async flow updates require stream support
        Ok(vec![])
    }

    /// Send packet_out
    async fn send_packet_out(&self, handle: &str, packet_out_json: &str) -> zbus::Result<String> {
        let conns = self.connections.read().await;
        let vconn = conns.get(handle)
            .ok_or_else(|| zbus::Error::InvalidArgs(format!("invalid handle: {}", handle)))?;

        let packet_out: rovs_openflow::PacketOut = serde_json::from_str(packet_out_json)
            .map_err(|e| zbus::Error::InvalidArgs(format!("invalid packet_out JSON: {}", e)))?;

        let mut vconn = vconn.lock().await;
        vconn.send_packet_out(&packet_out)
            .await
            .map_err(|e| zbus::Error::Io(std::io::Error::new(
                std::io::ErrorKind::Other, format!("send_packet_out failed: {}", e)
            )))?;

        Ok(format!("{{\"sent\":true,\"handle\":\"{}\"}}", handle))
    }

    /// Raw ovs-ofctl passthrough (temporary compatibility)
    async fn ofctl(&self, bridge: &str, args_json: &str) -> zbus::Result<String> {
        // This is a shim for ovs-ofctl compatibility
        // Full implementation would use VConn methods
        warn!("ofctl called for bridge {} - implementing as no-op", bridge);
        Ok(format!("{{\"bridge\":\"{}\",\"args\":{},\"status\":\"shim\"}}", bridge, args_json))
    }

    /// Controller status JSON
    async fn status(&self) -> zbus::Result<String> {
        let conns = self.connections.read().await;
        let handles: Vec<String> = conns.keys().cloned().collect();

        let status = serde_json::json!({
            "service": "op-openvswitch-daemon",
            "version": env!("CARGO_PKG_VERSION"),
            "openflow": {
                "listen_addr": self.listen_addr.to_string(),
                "active_connections": handles.len(),
                "handles": handles,
            },
        });
        Ok(status.to_string())
    }
}

impl RovsOpenFlowInterface {
    fn new(listen_addr: SocketAddr) -> Self {
        Self {
            connections: Arc::new(RwLock::new(HashMap::new())),
            next_id: Arc::new(Mutex::new(1)),
            listen_addr,
        }
    }

    async fn allocate_id(&self) -> String {
        let mut id = self.next_id.lock().await;
        let result = format!("vconn-{}", *id);
        *id += 1;
        result
    }

    /// Spawn passive OpenFlow controller listener (absorbs op-of-controller)
    async fn spawn_passive_listener(&self) -> Result<()> {
        let listener = TcpListener::bind(self.listen_addr)
            .await
            .with_context(|| format!("binding OpenFlow controller on {}", self.listen_addr))?;

        info!("OpenFlow controller listening on {}", self.listen_addr);

        let connections = self.connections.clone();
        let next_id = self.next_id.clone();

        tokio::spawn(async move {
            loop {
                match listener.accept().await {
                    Ok((stream, peer)) => {
                        info!("OpenFlow: incoming connection from {}", peer);

                        let stream = Stream::Tcp(stream);
                        match VConn::new(stream).await {
                            Ok(vconn) => {
                                let id = {
                                    let mut id = next_id.lock().await;
                                    let result = format!("vconn-passive-{}", *id);
                                    *id += 1;
                                    result
                                };

                                let mut conns = connections.write().await;
                                conns.insert(id.clone(), Arc::new(Mutex::new(vconn)));
                                info!("OpenFlow: passive connection {} established", id);
                            }
                            Err(e) => {
                                warn!("OpenFlow: handshake failed from {}: {}", peer, e);
                            }
                        }
                    }
                    Err(e) => {
                        warn!("OpenFlow: accept failed: {}", e);
                    }
                }
            }
        });

        Ok(())
    }
}

// ── Main ──────────────────────────────────────────────────────────────────────

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt::init();

    info!("Starting op-openvswitch-daemon...");

    // Connect to OVSDB socket
    let jsonrpc_stream = Stream::connect_unix(OVSDB_SOCKET)
        .await
        .with_context(|| format!("connecting to OVSDB socket at {}", OVSDB_SOCKET))?;

    let jsonrpc_conn = JsonRpcConnection::new(jsonrpc_stream)
        .await
        .context("establishing JSON-RPC connection")?;

    info!("Connected to OVSDB at {}", OVSDB_SOCKET);

    // Create JSON-RPC interface
    let jsonrpc_iface = RovsJsonRpcInterface {
        conn: Arc::new(Mutex::new(jsonrpc_conn)),
        notification_buffer: Arc::new(Mutex::new(Vec::new())),
    };

    // Create OpenFlow interface with passive listener
    let of_listen_addr: SocketAddr = format!("0.0.0.0:{}", OF_CONTROLLER_PORT).parse()?;
    let openflow_iface = RovsOpenFlowInterface::new(of_listen_addr);

    // Spawn passive OpenFlow listener
    openflow_iface.spawn_passive_listener().await?;

    // Build D-Bus connection
    let conn = connection::Builder::system()?
        .name(SYSTEM_BUS_DEST)?
        .serve_at(JSONRPC_PATH, jsonrpc_iface)?
        .serve_at(OPENFLOW_PATH, openflow_iface)?
        .build()
        .await
        .context("building D-Bus connection")?;

    info!("op-openvswitch-daemon ready on system bus");
    info!("  JSON-RPC: {}", JSONRPC_PATH);
    info!("  OpenFlow: {}", OPENFLOW_PATH);
    info!("  OF controller port: {}", OF_CONTROLLER_PORT);

    // Keep running
    tokio::signal::ctrl_c().await?;
    info!("Shutting down op-openvswitch-daemon...");

    Ok(())
}

