//! D-Bus proxies for the op-openvswitch-daemon
//!
//! These zbus proxy types allow any crate in the workspace to call the
//! hypervisor daemon through D-Bus instead of directly linking rovs_ovsdb
//! or shelling out to ovs-vsctl / ovs-ofctl.
//!
//! Locked design (AGENTS.md §4):
//! - Daemon paths: `/org/opdbus/rovs/jsonrpc` and `/org/opdbus/rovs/openflow`
//! - Interfaces: `org.opdbus.rovs.jsonrpc` and `org.opdbus.rovs.openflow`
//! - The daemon is a pure passthrough; business logic stays in the plugins.

use anyhow::{Context, Result};
use std::sync::Arc;
use zbus::{proxy, Connection};

// ── RovsJsonRpcProxy ──────────────────────────────────────────────────────────

/// Proxy for the OVSDB JSON-RPC passthrough interface.
///
/// D-Bus destination: `org.opdbus.v1`
/// Object path: `/org/opdbus/rovs/jsonrpc`
/// Interface: `org.opdbus.rovs.jsonrpc`
#[proxy(
    default_service = "org.opdbus.v1",
    default_path = "/org/opdbus/rovs/jsonrpc",
    interface = "org.opdbus.rovs.jsonrpc"
)]
pub trait RovsJsonRpc {
    /// Execute a raw OVSDB JSON-RPC `transact`.
    ///
    /// `method` is the JSON-RPC method name (e.g. `"transact"`).
    /// `params_json` is the JSON-encoded parameter array.
    /// Returns the JSON-encoded result.
    async fn transact(&self, method: &str, params_json: &str) -> zbus::Result<String>;

    /// Execute a one-way OVSDB JSON-RPC `notify`.
    async fn notify(&self, method: &str, params_json: &str) -> zbus::Result<()>;

    /// Return the next JSON-RPC request id.
    async fn next_id(&self) -> zbus::Result<u64>;

    /// Send a raw JSON-RPC message string and return the response string.
    async fn send_message(&self, msg: &str) -> zbus::Result<String>;

    /// Receive a raw JSON-RPC message string.
    async fn recv_message(&self) -> zbus::Result<String>;

    /// Poll whether notification queue has pending items.
    async fn has_pending_notifications(&self) -> zbus::Result<bool>;

    /// Return the count of pending notifications.
    async fn pending_notification_count(&self) -> zbus::Result<u64>;

    /// Pop one notification from the queue as a JSON string.
    async fn pop_notification(&self) -> zbus::Result<String>;

    /// Drain all pending notifications as a JSON array string.
    async fn drain_notifications(&self) -> zbus::Result<String>;

    /// Open a new named stream / monitor.
    async fn new_stream(&self, stream: &str) -> zbus::Result<String>;

    /// Daemon status JSON.
    async fn status(&self) -> zbus::Result<String>;
}

/// Convenience constructor: build a `RovsJsonRpcProxy` on the system bus.
pub async fn jsonrpc_proxy() -> Result<RovsJsonRpcProxy<'static>> {
    let conn = Connection::system()
        .await
        .context("connect to system D-Bus for RovsJsonRpcProxy")?;
    Ok(RovsJsonRpcProxy::new(&conn).await?)
}

// ── RovsOpenFlowProxy ─────────────────────────────────────────────────────────

/// Proxy for the OpenFlow passthrough interface.
///
/// D-Bus destination: `org.opdbus.v1`
/// Object path: `/org/opdbus/rovs/openflow`
/// Interface: `org.opdbus.rovs.openflow`
#[proxy(
    default_service = "org.opdbus.v1",
    default_path = "/org/opdbus/rovs/openflow",
    interface = "org.opdbus.rovs.openflow"
)]
pub trait RovsOpenFlow {
    /// Connect to a switch at `addr` (e.g. `"tcp:127.0.0.1:6653"`).
    /// Returns connection handle id or error JSON.
    async fn connect(&self, addr: &str) -> zbus::Result<String>;

    /// Return negotiated OpenFlow version JSON.
    async fn version(&self) -> zbus::Result<String>;

    /// Send a flow_mod. `flow_json` is a JSON-encoded Flow struct.
    async fn send_flow(&self, flow_json: &str) -> zbus::Result<String>;

    /// Send a flow_mod and wait for barrier reply.
    async fn send_flow_sync(&self, flow_json: &str) -> zbus::Result<String>;

    /// Raw `ovs-ofctl` passthrough (temporary until pure OpenFlow binary is wired).
    /// `bridge` is the bridge name, `args_json` is a JSON array of extra CLI args.
    async fn ofctl(&self, bridge: &str, args_json: &str) -> zbus::Result<String>;

    /// Send an echo request, return echo reply JSON.
    async fn echo(&self) -> zbus::Result<String>;

    /// Send a barrier request, return barrier reply JSON.
    async fn barrier(&self) -> zbus::Result<String>;

    /// Dump all flows. Returns JSON array of FlowStatsEntry.
    async fn dump_flows(&self) -> zbus::Result<Vec<String>>;

    /// Dump flows matching a filter request JSON.
    async fn dump_flows_filtered(&self, request: &str) -> zbus::Result<Vec<String>>;

    /// Block until a PacketIn message arrives. Returns JSON PacketIn.
    async fn recv_packet_in(&self) -> zbus::Result<String>;

    /// Non-blocking try-receive PacketIn. Returns JSON or empty string.
    async fn try_recv_packet_in(&self) -> zbus::Result<String>;

    /// Start flow monitor with request JSON. Returns initial updates.
    async fn monitor_flows(&self, request: &str) -> zbus::Result<Vec<String>>;

    /// Block until flow updates arrive. Returns JSON array of FlowUpdate.
    async fn recv_flow_updates(&self) -> zbus::Result<Vec<String>>;

    /// Send a packet_out. `packet_out_json` is JSON-encoded PacketOut.
    async fn send_packet_out(&self, packet_out_json: &str) -> zbus::Result<String>;

    /// Controller status JSON.
    async fn status(&self) -> zbus::Result<String>;
}

/// Convenience constructor: build a `RovsOpenFlowProxy` on the system bus.
pub async fn openflow_proxy() -> Result<RovsOpenFlowProxy<'static>> {
    let conn = Connection::system()
        .await
        .context("connect to system D-Bus for RovsOpenFlowProxy")?;
    Ok(RovsOpenFlowProxy::new(&conn).await?)
}

// ── Unified helper ────────────────────────────────────────────────────────────

/// Ensure the op-openvswitch-daemon is reachable on D-Bus before proceeding.
///
/// This is the preferred entry-point for plugins: call this, then use the
/// returned proxies instead of `OvsdbClient` or `Command::new("ovs-vsctl")`.
pub async fn ensure_proxies() -> Result<(RovsJsonRpcProxy<'static>, RovsOpenFlowProxy<'static>)> {
    let json = jsonrpc_proxy().await?;
    let of = openflow_proxy().await?;
    Ok((json, of))
}

// ── OvsdbDbusClient ─────────────────────────────────────────────────────────

/// High-level OVSDB client that routes through the D-Bus daemon.
///
/// Mirrors the `OvsdbClient` API so plugin migrations are mechanical.
///
/// Construction is **synchronous** (like the original `OvsdbClient`) — the
/// underlying D-Bus connection is established lazily on the first async call.
/// This lets `StatePlugin::new()` stay sync.
#[derive(Clone)]
pub struct OvsdbDbusClient {
    proxy: Arc<tokio::sync::OnceCell<RovsJsonRpcProxy<'static>>>,
}

impl Default for OvsdbDbusClient {
    fn default() -> Self {
        Self::new()
    }
}

impl OvsdbDbusClient {
    /// Synchronous constructor — D-Bus connection is deferred until first use.
    pub fn new() -> Self {
        Self {
            proxy: Arc::new(tokio::sync::OnceCell::new()),
        }
    }

    /// Internal: get or create the proxy.
    async fn get_proxy(&self) -> Result<&RovsJsonRpcProxy<'static>> {
        self.proxy
            .get_or_try_init(|| async { jsonrpc_proxy().await })
            .await
            .context("connect to op-openvswitch-daemon via D-Bus")
    }

    // ── Internal: build & send a transact ───────────────────────────────

    async fn transact_one(&self, op: serde_json::Value) -> Result<serde_json::Value> {
        let proxy = self.get_proxy().await?;
        let params = serde_json::json!(["Open_vSwitch", op]);
        let raw = proxy
            .transact("transact", &params.to_string())
            .await
            .context("D-Bus transact call failed")?;
        let val: serde_json::Value = serde_json::from_str(&raw)
            .with_context(|| format!("daemon returned invalid JSON: {}", raw))?;
        Ok(val)
    }

    async fn transact_many(&self, ops: Vec<serde_json::Value>) -> Result<serde_json::Value> {
        let proxy = self.get_proxy().await?;
        let params = serde_json::json!(["Open_vSwitch", ops]);
        let raw = proxy
            .transact("transact", &params.to_string())
            .await
            .context("D-Bus transact call failed")?;
        let val: serde_json::Value = serde_json::from_str(&raw)
            .with_context(|| format!("daemon returned invalid JSON: {}", raw))?;
        Ok(val)
    }

    // ── Read helpers ──────────────────────────────────────────────────────

    /// Return `true` if the daemon (and OVSDB) is reachable.
    pub async fn list_dbs(&self) -> Result<Vec<String>> {
        let proxy = self.get_proxy().await?;
        let raw = proxy
            .transact("list_dbs", "[]")
            .await
            .context("list_dbs D-Bus call failed")?;
        let val: serde_json::Value = serde_json::from_str(&raw)?;
        Ok(val
            .as_array()
            .cloned()
            .unwrap_or_default()
            .iter()
            .filter_map(|v| v.as_str().map(String::from))
            .collect())
    }

    /// Return `true` if a bridge with the given name exists.
    pub async fn bridge_exists(&self, bridge_name: &str) -> Result<bool> {
        let result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": ["_uuid"]
            }))
            .await?;
        Ok(result
            .get("rows")
            .and_then(|r| r.as_array())
            .map(|a| !a.is_empty())
            .unwrap_or(false))
    }

    /// Return the names of all bridges.
    pub async fn list_bridges(&self) -> Result<Vec<String>> {
        let result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [],
                "columns": ["name"]
            }))
            .await?;
        Ok(result
            .get("rows")
            .and_then(|r| r.as_array())
            .cloned()
            .unwrap_or_default()
            .iter()
            .filter_map(|r| r.get("name").and_then(|v| v.as_str()).map(String::from))
            .collect())
    }

    /// Return the names of all ports on a bridge.
    pub async fn list_bridge_ports(&self, bridge_name: &str) -> Result<Vec<String>> {
        let bridge_result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": ["ports"]
            }))
            .await?;
        let bridge_rows = bridge_result.get("rows").and_then(|r| r.as_array());
        let port_uuids: Vec<String> = match bridge_rows {
            Some(rows) if !rows.is_empty() => {
                let mut uuids = Vec::new();
                if let Some(ports) = rows[0].get("ports") {
                    Self::collect_uuids(ports, &mut uuids);
                }
                uuids
            }
            _ => return Ok(Vec::new()),
        };

        let mut names = Vec::new();
        for uuid in port_uuids {
            let result = self
                .transact_one(serde_json::json!({
                    "op": "select",
                    "table": "Port",
                    "where": [["_uuid", "==", ["uuid", uuid]]],
                    "columns": ["name"]
                }))
                .await?;
            if let Some(row) = result.get("rows").and_then(|r| r.as_array()).and_then(|a| a.first())
            {
                if let Some(n) = row.get("name").and_then(|v| v.as_str()) {
                    names.push(n.to_string());
                }
            }
        }
        Ok(names)
    }

    /// Return the raw JSON row for a bridge.
    pub async fn get_bridge_info(&self, bridge_name: &str) -> Result<String> {
        let result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": []
            }))
            .await?;
        Ok(serde_json::to_string_pretty(&result)?)
    }

    // ── Mutation helpers ──────────────────────────────────────────────────

    /// Create a bridge if it does not exist.
    pub async fn create_bridge(&self, bridge_name: &str) -> Result<()> {
        if self.bridge_exists(bridge_name).await? {
            log::info!("Bridge {} already exists, skipping creation", bridge_name);
            return Ok(());
        }
        let ops = vec![
            serde_json::json!({
                "op": "insert",
                "table": "Bridge",
                "row": { "name": bridge_name, "stp_enable": false },
                "uuid-name": "new_bridge"
            }),
            serde_json::json!({
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [],
                "mutations": [["bridges", "insert", ["named-uuid", "new_bridge"]]]
            }),
        ];
        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!("Bridge {} created via D-Bus daemon", bridge_name);
        Ok(())
    }

    /// Delete a bridge and its ports/interfaces.
    pub async fn delete_bridge(&self, bridge_name: &str) -> Result<()> {
        let bridge_result = self
            .transact_one(serde_json::json!({
                "op": "select",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "columns": ["_uuid", "ports"]
            }))
            .await?;
        let bridge_rows = bridge_result.get("rows").and_then(|r| r.as_array());
        let (bridge_uuid, bridge_row) = match bridge_rows {
            Some(rows) if !rows.is_empty() => {
                let uuid = rows[0].get("_uuid")
                    .and_then(|u| u.as_array())
                    .and_then(|a| a.get(1))
                    .and_then(|v| v.as_str())
                    .map(String::from)
                    .ok_or_else(|| anyhow::anyhow!("bridge UUID not found"))?;
                (uuid, &rows[0])
            }
            _ => return Err(anyhow::anyhow!("Bridge '{}' not found", bridge_name)),
        };

        let mut port_uuids: Vec<String> = Vec::new();
        if let Some(ports) = bridge_row.get("ports") {
            Self::collect_uuids(ports, &mut port_uuids);
        }

        let mut iface_uuids: Vec<String> = Vec::new();
        for port_uuid in &port_uuids {
            let port_result = self
                .transact_one(serde_json::json!({
                    "op": "select",
                    "table": "Port",
                    "where": [["_uuid", "==", ["uuid", port_uuid.clone()]]],
                    "columns": ["interfaces"]
                }))
                .await?;
            if let Some(rows) = port_result.get("rows").and_then(|r| r.as_array()) {
                if let Some(row) = rows.first() {
                    if let Some(ifaces) = row.get("interfaces") {
                        Self::collect_uuids(ifaces, &mut iface_uuids);
                    }
                }
            }
        }

        let mut ops = vec![
            serde_json::json!({
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [],
                "mutations": [["bridges", "delete", ["uuid", bridge_uuid.clone()]]]
            }),
            serde_json::json!({
                "op": "delete",
                "table": "Bridge",
                "where": [["_uuid", "==", ["uuid", bridge_uuid]]]
            }),
        ];
        for port_uuid in &port_uuids {
            ops.push(serde_json::json!({
                "op": "delete",
                "table": "Port",
                "where": [["_uuid", "==", ["uuid", port_uuid]]]
            }));
        }
        for iface_uuid in &iface_uuids {
            ops.push(serde_json::json!({
                "op": "delete",
                "table": "Interface",
                "where": [["_uuid", "==", ["uuid", iface_uuid]]]
            }));
        }

        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!("Bridge {} deleted via D-Bus daemon", bridge_name);
        Ok(())
    }

    /// Add a system port to a bridge.
    pub async fn add_port(&self, bridge_name: &str, port_name: &str) -> Result<()> {
        let ops = vec![
            serde_json::json!({
                "op": "insert",
                "table": "Interface",
                "row": { "name": port_name, "type": "system" },
                "uuid-name": "new_iface"
            }),
            serde_json::json!({
                "op": "insert",
                "table": "Port",
                "row": {
                    "name": port_name,
                    "interfaces": ["set", [["named-uuid", "new_iface"]]]
                },
                "uuid-name": "new_port"
            }),
            serde_json::json!({
                "op": "mutate",
                "table": "Bridge",
                "where": [["name", "==", bridge_name]],
                "mutations": [["ports", "insert", ["named-uuid", "new_port"]]]
            }),
        ];
        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!("Port {} added to bridge {} via D-Bus daemon", port_name, bridge_name);
        Ok(())
    }

    // ── Private helpers ───────────────────────────────────────────────────

    /// Recursively collect UUID strings from an OVSDB set value.
    fn collect_uuids(value: &serde_json::Value, out: &mut Vec<String>) {
        if let Some(arr) = value.as_array() {
            if arr.len() == 2 {
                if arr[0] == "uuid" {
                    if let Some(s) = arr[1].as_str() {
                        out.push(s.to_string());
                    }
                } else if arr[0] == "set" {
                    if let Some(items) = arr[1].as_array() {
                        for item in items {
                            Self::collect_uuids(item, out);
                        }
                    }
                }
            }
        }
    }

    /// Check a transact result for per-operation error objects.
    fn check_errors(result: &serde_json::Value) -> Result<()> {
        if let Some(results) = result.as_array() {
            for (i, op_result) in results.iter().enumerate() {
                if let Some(error) = op_result.get("error") {
                    if !error.is_null() {
                        let details = op_result
                            .get("details")
                            .and_then(|d| d.as_str())
                            .unwrap_or("no details");
                        return Err(anyhow::anyhow!(
                            "OVSDB operation {} failed: {} ({})",
                            i,
                            error,
                            details
                        ));
                    }
                }
            }
        }
        Ok(())
    }

    /// Set the `type` column on an Interface row (e.g. "internal", "system").
    pub async fn set_interface_type(&self, iface_name: &str, iface_type: &str) -> Result<()> {
        let ops = vec![
            serde_json::json!({
                "op": "update",
                "table": "Interface",
                "where": [["name", "==", iface_name]],
                "row": { "type": iface_type }
            }),
        ];
        let result = self.transact_many(ops).await?;
        Self::check_errors(&result)?;
        log::info!("Interface {} type set to {} via D-Bus daemon", iface_name, iface_type);
        Ok(())
    }

    /// Compatibility shim for plugins that pass `simd_json::OwnedValue`.
    /// Converts to `serde_json::Value` and routes through the D-Bus daemon.
    pub async fn transact_simd(&self, operations: simd_json::OwnedValue) -> Result<serde_json::Value> {
        let text = simd_json::to_string(&operations)
            .context("failed to serialize simd_json operations to JSON text")?;
        let converted: serde_json::Value = serde_json::from_str(&text)
            .context("failed to deserialize simd_json operations as serde_json::Value")?;
        self.transact_many(converted.as_array().cloned().unwrap_or_default()).await
    }
}

//! OpenFlow 1.3 controller server (passive mode)
//!
//! Listens for OVS to connect (passive mode), performs the OF1.3 handshake,
//! discovers port numbers by name via a PortDesc multipart request, clears all
//! existing flows, and installs the configured forwarding rules.
//!
//! Wire-protocol encoding is delegated to `rovs_openflow` types wherever
//! possible; the TCP listener and passive handshake are implemented here
//! because `rovs_openflow::VConn` only supports active (outbound) connections.

use anyhow::{Context, Result};
use bytes::Bytes;
use rovs_openflow::{ActionList, Flow, Match, Message, MessageType, OutputPort, Version};
use rovs_transport::Reconnect;
use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::Arc;
use std::time::Duration;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};

// ── OF1.3 constants ────────────────────────────────────────────────────────────

/// Multipart type: port description.
const OFPMP_PORT_DESC: u16 = 13;
/// "All" output port — used when out_port is not restricted.
const OFPP_ANY: u32 = 0xFFFF_FFFF;

// ── Wire helpers ──────────────────────────────────────────────────────────────

/// Build a raw OF1.3 message with an 8-byte header and `body`.
fn build_raw_msg(msg_type: MessageType, xid: u32, body: &[u8]) -> Vec<u8> {
    let msg = Message::new(Version::Of13, msg_type, xid, Bytes::copy_from_slice(body));
    msg.encode().to_vec()
}

/// Build an OF1.3 Hello message.
fn build_hello(xid: u32) -> Vec<u8> {
    build_raw_msg(MessageType::Hello, xid, &[])
}

/// Build an OF1.3 FeaturesRequest message.
fn build_features_request(xid: u32) -> Vec<u8> {
    build_raw_msg(MessageType::FeaturesRequest, xid, &[])
}

/// Build an OF1.3 PortDesc multipart request.
///
/// Body: type(2) + flags(2) + pad(4) = 8 bytes.
fn build_port_desc_request(xid: u32) -> Vec<u8> {
    let mut body = [0u8; 8];
    body[0..2].copy_from_slice(&OFPMP_PORT_DESC.to_be_bytes());
    build_raw_msg(MessageType::MultipartRequest, xid, &body)
}

/// Build an OF1.3 EchoReply that mirrors the request payload.
fn build_echo_reply(xid: u32, payload: &[u8]) -> Vec<u8> {
    build_raw_msg(MessageType::EchoReply, xid, payload)
}

/// Build an OF1.3 FlowMod DELETE ALL (wildcard match, all tables).
fn build_flow_mod_delete_all(xid: u32) -> Vec<u8> {
    let flow = Flow::delete();
    let msg = flow.to_message(Version::Of13, xid);
    msg.encode().to_vec()
}

/// Build an OF1.3 FlowMod ADD: match `in_port`, output to `out_port`.
pub fn build_flow_mod_add(in_port: u32, out_port: u32, priority: u16, xid: u32) -> Vec<u8> {
    let match_fields = Match::new().in_port(in_port);
    let actions = ActionList::new().output(OutputPort::Port(out_port));
    let flow = Flow::add()
        .priority(priority)
        .match_fields(match_fields)
        .actions(actions);
    let msg = flow.to_message(Version::Of13, xid);
    msg.encode().to_vec()
}

// ── Raw message receive ───────────────────────────────────────────────────────

/// A raw inbound OpenFlow message (header parsed, body buffered).
struct RawMsg {
    msg_type: u8,
    xid: u32,
    payload: Vec<u8>,
}

/// Read one complete OpenFlow message from `stream`.
async fn recv_msg(stream: &mut TcpStream) -> Result<RawMsg> {
    let mut hdr = [0u8; 8];
    stream
        .read_exact(&mut hdr)
        .await
        .context("reading OF header")?;

    let msg_type = hdr[1];
    let length = u16::from_be_bytes([hdr[2], hdr[3]]) as usize;
    let xid = u32::from_be_bytes([hdr[4], hdr[5], hdr[6], hdr[7]]);
    let payload_len = length.saturating_sub(8);

    let mut payload = vec![0u8; payload_len];
    if payload_len > 0 {
        stream
            .read_exact(&mut payload)
            .await
            .context("reading OF payload")?;
    }

    Ok(RawMsg {
        msg_type,
        xid,
        payload,
    })
}

/// Write raw bytes to `stream`.
async fn send_msg(stream: &mut TcpStream, bytes: &[u8]) -> Result<()> {
    stream.write_all(bytes).await.context("sending OF message")
}

// ── Port discovery ─────────────────────────────────────────────────────────────

/// Send a PortDesc request and parse all replies into `{port_name → ofport_no}`.
async fn discover_ports(stream: &mut TcpStream, xid: u32) -> Result<HashMap<String, u32>> {
    send_msg(stream, &build_port_desc_request(xid)).await?;

    let mut ports: HashMap<String, u32> = HashMap::new();

    loop {
        let msg = recv_msg(stream).await?;
        match msg.msg_type {
            // Echo request — must reply to stay alive during discovery.
            2 /* EchoRequest */ => {
                send_msg(stream, &build_echo_reply(msg.xid, &msg.payload)).await?;
            }
            // MultipartReply (19)
            19 => {
                if msg.payload.len() < 8 {
                    break;
                }
                let reply_type = u16::from_be_bytes([msg.payload[0], msg.payload[1]]);
                let flags = u16::from_be_bytes([msg.payload[2], msg.payload[3]]);

                if reply_type == OFPMP_PORT_DESC {
                    // OF1.3 ofp_port = 64 bytes:
                    // port_no(4) pad(4) hw_addr(6) pad(2) name(16) config(4) state(4)
                    // curr(4) advertised(4) supported(4) peer(4) curr_speed(4) max_speed(4)
                    let body = &msg.payload[8..];
                    for chunk in body.chunks_exact(64) {
                        let port_no =
                            u32::from_be_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
                        let name = String::from_utf8_lossy(&chunk[16..32])
                            .trim_end_matches('\0')
                            .to_string();
                        if !name.is_empty() && port_no < OFPP_ANY {
                            ports.insert(name, port_no);
                        }
                    }
                    // bit 0 of flags = OFPMPF_REPLY_MORE
                    if flags & 1 == 0 {
                        break;
                    }
                } else {
                    break;
                }
            }
            _ => break,
        }
    }

    Ok(ports)
}

// ── Connection handler ────────────────────────────────────────────────────────

/// Handle one inbound OVS connection: handshake → port discovery → flow install → keepalive.
async fn handle_connection(
    mut stream: TcpStream,
    flows: Arc<Vec<(String, String, u16)>>,
) -> Result<()> {
    let mut xid: u32 = 1;

    // 1. Receive Hello from OVS.
    let hello = recv_msg(&mut stream).await?;
    if hello.msg_type != 0 {
        anyhow::bail!("expected Hello (type 0), got msg_type={}", hello.msg_type);
    }

    // 2. Send Hello.
    send_msg(&mut stream, &build_hello(xid)).await?;
    xid += 1;

    // 3. Send FeaturesRequest; wait for FeaturesReply (type 6), echo any pings.
    send_msg(&mut stream, &build_features_request(xid)).await?;
    xid += 1;

    loop {
        let msg = recv_msg(&mut stream).await?;
        match msg.msg_type {
            2 /* EchoRequest */ => {
                send_msg(&mut stream, &build_echo_reply(msg.xid, &msg.payload)).await?;
            }
            6 /* FeaturesReply */ => break,
            _ => {}
        }
    }

    // 4. Discover ports via PortDesc multipart.
    let port_map = discover_ports(&mut stream, xid).await?;
    xid += 1;

    log::info!(
        "OF controller: discovered {} ports: {:?}",
        port_map.len(),
        port_map.keys().collect::<Vec<_>>()
    );

    // 5. Delete all existing flows.
    send_msg(&mut stream, &build_flow_mod_delete_all(xid)).await?;
    xid += 1;

    // 6. Install configured flows.
    let mut installed = 0u32;
    for (in_name, out_name, priority) in flows.iter() {
        match (
            port_map.get(in_name.as_str()),
            port_map.get(out_name.as_str()),
        ) {
            (Some(&in_port), Some(&out_port)) => {
                send_msg(
                    &mut stream,
                    &build_flow_mod_add(in_port, out_port, *priority, xid),
                )
                .await?;
                xid += 1;
                installed += 1;
                log::info!(
                    "OF controller: installed flow {} (port {}) → {} (port {}), priority={}",
                    in_name,
                    in_port,
                    out_name,
                    out_port,
                    priority
                );
            }
            _ => {
                log::warn!(
                    "OF controller: port not found for flow {} → {} (known: {:?})",
                    in_name,
                    out_name,
                    port_map.keys().collect::<Vec<_>>()
                );
            }
        }
    }

    log::info!(
        "OF controller: {} flows installed; entering keepalive loop",
        installed
    );

    // 7. Keepalive loop — reply to Echo requests indefinitely.
    loop {
        let msg = recv_msg(&mut stream).await?;
        if msg.msg_type == 2
        /* EchoRequest */
        {
            send_msg(&mut stream, &build_echo_reply(msg.xid, &msg.payload)).await?;
        }
    }
}

// ── Public API ────────────────────────────────────────────────────────────────

/// OpenFlow 1.3 controller — accepts connections from OVS and installs flows.
///
/// OVS connects *to* the controller (not the other way around).
/// Configure OVS with: `ovs-vsctl set-controller ovsbr0 tcp:<listen_addr>`
pub struct OpenFlowController {
    listen_addr: SocketAddr,
    flows: Vec<(String, String, u16)>,
}

impl OpenFlowController {
    /// Create a new controller that will listen on `listen_addr`.
    pub fn new(listen_addr: SocketAddr) -> Self {
        Self {
            listen_addr,
            flows: Vec::new(),
        }
    }

    /// Add a bidirectional forwarding pair (installs two flows: A→B and B→A).
    pub fn add_port_pair(mut self, port_a: &str, port_b: &str, priority: u16) -> Self {
        self.flows
            .push((port_a.to_string(), port_b.to_string(), priority));
        self.flows
            .push((port_b.to_string(), port_a.to_string(), priority));
        self
    }

    /// Add a single directed flow (in_port → out_port).
    pub fn add_flow(mut self, in_port: &str, out_port: &str, priority: u16) -> Self {
        self.flows
            .push((in_port.to_string(), out_port.to_string(), priority));
        self
    }

    /// Run the controller — listens for OVS connections and re-programs flows on each reconnect.
    ///
    /// Each spawned connection handler maintains its own `Reconnect` state machine so
    /// that rapid repeated failures (e.g. OVS flapping) are logged with backoff information
    /// rather than silently spinning.
    pub async fn run(self) -> Result<()> {
        let listener = TcpListener::bind(self.listen_addr)
            .await
            .with_context(|| format!("binding OpenFlow controller on {}", self.listen_addr))?;

        log::info!("OpenFlow controller listening on {}", self.listen_addr);

        let flows = Arc::new(self.flows);

        loop {
            let (stream, peer) = listener.accept().await?;
            let flows = flows.clone();
            log::info!("OpenFlow controller: OVS connected from {}", peer);

            tokio::spawn(async move {
                // Per-connection reconnection tracker.  OVS is the active side so
                // we don't drive the reconnect loop ourselves — we just record state
                // and log when failures come in rapidly so operators see backoff hints.
                let mut reconnect = Reconnect::new();
                reconnect.set_max_backoff(Duration::from_secs(30));
                reconnect.connecting();

                match handle_connection(stream, flows).await {
                    Ok(()) => {
                        // Clean close — mark disconnected so next accept starts fresh.
                        reconnect.disconnected();
                        log::info!("OF controller: connection from {} closed cleanly", peer);
                    }
                    Err(e) => {
                        reconnect.disconnected();
                        reconnect.increase_backoff();
                        log::warn!(
                            "OF controller: connection from {} ended with error \
                             (next OVS reconnect backoff hint: {:?}): {:#}",
                            peer,
                            reconnect.current_backoff(),
                            e
                        );
                    }
                }
            });
        }
    }
}

// ── Tests ─────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_flow_mod_add_length() {
        let msg = build_flow_mod_add(6, 7, 100, 1);
        let declared_len = u16::from_be_bytes([msg[2], msg[3]]) as usize;
        assert_eq!(declared_len, msg.len(), "declared length must match actual");
        // OF1.3 version byte
        assert_eq!(msg[0], 0x04);
        // FlowMod type = 14
        assert_eq!(msg[1], 14);
    }

    #[test]
    fn test_flow_mod_delete_all() {
        let msg = build_flow_mod_delete_all(1);
        let declared_len = u16::from_be_bytes([msg[2], msg[3]]) as usize;
        assert_eq!(declared_len, msg.len(), "declared length must match actual");
        assert_eq!(msg[0], 0x04); // OF1.3
        assert_eq!(msg[1], 14); // FlowMod
    }
}

//! op-openvswitch-daemon — Pure passthrough D-Bus proxy for rovs primitives.
//!
//! TWO separate D-Bus object paths (locked design):
//! - `/org/opdbus/rovs/jsonrpc`  → `org.opdbus.rovs.jsonrpc`
//! - `/org/opdbus/rovs/openflow` → `org.opdbus.rovs.openflow`
//!
//! The daemon is a literal passthrough: it owns the rovs crate connections
//! and exposes raw primitives over D-Bus.  Zero business logic.
//!
//! Per AGENTS.md §4: D-Bus is the ONLY control plane.

use anyhow::{Context, Result};
use std::path::Path;
use tracing::{info, warn};
use zbus::connection::Connection;

mod dbus;
mod execution;
mod grpc;

use dbus::{DaemonState, JsonRpcService, OpenFlowService};
use execution::PluginExecutionService;

// ── CLI ───────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
struct Args {
    grpc_addr: Option<String>,
    ovs_socket: Option<String>,
}

impl Args {
    fn parse() -> Self {
        let args: Vec<String> = std::env::args().collect();
        let mut grpc_addr = None;
        let mut ovs_socket = None;
        let mut i = 1;
        while i < args.len() {
            match args[i].as_str() {
                "--grpc" => {
                    if i + 1 < args.len() {
                        grpc_addr = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                "--ovs-socket" => {
                    if i + 1 < args.len() {
                        ovs_socket = Some(args[i + 1].clone());
                        i += 2;
                    } else {
                        i += 1;
                    }
                }
                _ => i += 1,
            }
        }
        Self {
            grpc_addr,
            ovs_socket,
        }
    }
}

// ── Socket discovery ────────────────────────────────────────────────────────

const DEFAULT_OVS_SOCKET: &str = "/var/run/openvswitch/db.sock";
const OVS_SOCKET_PATHS: &[&str] = &["/run/openvswitch/db.sock", "/var/run/openvswitch/db.sock"];

fn find_ovs_socket() -> String {
    OVS_SOCKET_PATHS
        .iter()
        .find(|p| Path::new(p).exists())
        .unwrap_or(&DEFAULT_OVS_SOCKET)
        .to_string()
}

// ── Main ────────────────────────────────────────────────────────────────────

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Starting op-openvswitch-daemon (pure passthrough)");

    let args = Args::parse();
    let socket_path = args.ovs_socket.unwrap_or_else(find_ovs_socket);
    info!("Using OVS socket: {}", socket_path);

    let state = DaemonState::new(socket_path);

    // Eager-connect OVSDB so early callers don't wait.
    if let Err(e) = state.get_ovsdb().await {
        warn!("Could not connect to OVSDB: {}. Will retry on first request.", e);
    }

    let conn = Connection::system()
        .await
        .context("Failed to connect to system D-Bus")?;
    info!("Connected to system D-Bus");

    // Register TWO separate object paths (locked design).
    let grpc_state = state.clone();
    let json_service = JsonRpcService::new(state.clone());
    let of_service = OpenFlowService::new(state);

    conn.object_server()
        .at("/org/opdbus/rovs/jsonrpc", json_service)
        .await
        .context("Failed to register /org/opdbus/rovs/jsonrpc")?;

    conn.object_server()
        .at("/org/opdbus/rovs/openflow", of_service)
        .await
        .context("Failed to register /org/opdbus/rovs/openflow")?;

    let exec_service = PluginExecutionService::new();
    conn.object_server()
        .at("/org/opdbus/execution", exec_service)
        .await
        .context("Failed to register /org/opdbus/execution")?;

    // Request single well-known bus name.
    conn.request_name("org.opdbus.v1")
        .await
        .context("Failed to request bus name org.opdbus.v1")?;

    info!("D-Bus services registered:");
    info!("  /org/opdbus/rovs/jsonrpc  -> org.opdbus.rovs.jsonrpc");
    info!("  /org/opdbus/rovs/openflow -> org.opdbus.rovs.openflow");
    info!("  /org/opdbus/execution     -> org.opdbus.execution");

    // Optional gRPC
    if let Some(grpc_addr) = args.grpc_addr {
        let addr: std::net::SocketAddr = grpc_addr
            .parse()
            .context("Invalid --grpc address")?;
        info!("Starting gRPC server on {}", addr);
        tokio::spawn(async move {
            if let Err(e) = grpc::run_grpc_server(addr, grpc_state).await {
                warn!("gRPC server error: {}", e);
            }
        });
    }

    info!("Daemon ready — Ctrl+C to stop");
    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;
    }
}

//! gRPC Service for OpenVSwitch Daemon
//!
//! Provides gRPC endpoints that mirror the D-Bus interface for OVSDB operations.
//! This allows remote clients to interact with OVS over gRPC while the daemon
//! maintains D-Bus as the canonical control plane per AGENTS.md.
//!
//! The gRPC service delegates to the same `DaemonState` used by the D-Bus
//! interfaces — zero duplication, zero drift.

use anyhow::Result;
use std::net::SocketAddr;
use tonic::{Request, Response, Status};
use tracing::info;

use crate::dbus::DaemonState;

/// Generated protobuf types
pub mod proto {
    tonic::include_proto!("ovsdaemon.v1");
}

use proto::ovsdb_service_server::{OvsdbService, OvsdbServiceServer};
use proto::{
    BridgeRequest, BridgeResponse, BridgesRequest, BridgesResponse,
    DatabaseRequest, DatabaseResponse, PortRequest, PortResponse,
    PortsRequest, PortsResponse, StatusRequest, StatusResponse,
};

/// gRPC service implementation — delegates to the shared `DaemonState`.
pub struct OvsdbServiceImpl {
    state: DaemonState,
}

impl OvsdbServiceImpl {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }

    /// Helper: acquire the OVSDB client from the shared state.
    async fn ovsdb_client(&self) -> Result<tokio::sync::MutexGuard<'_, Option<rovs_ovsdb::Client>>, Status> {
        self.state.get_ovsdb().await.map_err(|e| {
            Status::internal(format!("OVSDB not available: {}", e))
        })
    }
}

#[tonic::async_trait]
impl OvsdbService for OvsdbServiceImpl {
    async fn create_bridge(
        &self,
        request: Request<BridgeRequest>,
    ) -> Result<Response<BridgeResponse>, Status> {
        let name = request.into_inner().name;
        info!("gRPC create_bridge: {}", name);

        let mut guard = self.ovsdb_client().await?;
        let client = guard.as_mut().ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let ops = serde_json::json!([
            {
                "op": "insert",
                "table": "Bridge",
                "row": { "name": &name, "stp_enable": false },
                "uuid-name": "new_bridge"
            },
            {
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [],
                "mutations": [["bridges", "insert", ["named-uuid", "new_bridge"]]]
            },
        ]);

        match client.transact(ops).await {
            Ok(_) => Ok(Response::new(BridgeResponse {
                name,
                success: true,
                message: "Bridge created".to_string(),
            })),
            Err(e) => Ok(Response::new(BridgeResponse {
                name,
                success: false,
                message: format!("Failed: {}", e),
            })),
        }
    }

    async fn delete_bridge(
        &self,
        request: Request<BridgeRequest>,
    ) -> Result<Response<BridgeResponse>, Status> {
        let name = request.into_inner().name;
        info!("gRPC delete_bridge: {}", name);

        let mut guard = self.ovsdb_client().await?;
        let client = guard.as_mut().ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let del_ops = serde_json::json!([
            {
                "op": "delete",
                "table": "Bridge",
                "where": [["name", "==", &name]]
            },
            {
                "op": "mutate",
                "table": "Open_vSwitch",
                "where": [],
                "mutations": [["bridges", "delete", ["set", []]]]
            },
        ]);

        match client.transact(del_ops).await {
            Ok(_) => Ok(Response::new(BridgeResponse {
                name,
                success: true,
                message: "Bridge deleted".to_string(),
            })),
            Err(e) => Ok(Response::new(BridgeResponse {
                name,
                success: false,
                message: format!("Failed: {}", e),
            })),
        }
    }

    async fn list_bridges(
        &self,
        _request: Request<BridgesRequest>,
    ) -> Result<Response<BridgesResponse>, Status> {
        let mut guard = self.ovsdb_client().await?;
        let client = guard.as_mut().ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let ops = serde_json::json!([{
            "op": "select",
            "table": "Bridge",
            "where": [],
            "columns": ["name"]
        }]);

        match client.transact(ops).await {
            Ok(result) => {
                let bridges: Vec<String> = result
                    .get("rows")
                    .and_then(|r| r.as_array())
                    .cloned()
                    .unwrap_or_default()
                    .iter()
                    .filter_map(|r| r.get("name").and_then(|v| v.as_str()).map(String::from))
                    .collect();
                let count = bridges.len() as i32;
                Ok(Response::new(BridgesResponse { bridges, count }))
            }
            Err(e) => Err(Status::internal(format!("OVSDB query failed: {}", e))),
        }
    }

    async fn add_port(
        &self,
        request: Request<PortRequest>,
    ) -> Result<Response<PortResponse>, Status> {
        let req = request.into_inner();
        let name = req.name;
        let bridge = req.bridge;
        info!("gRPC add_port: {} to {}", name, bridge);

        let mut guard = self.ovsdb_client().await?;
        let client = guard.as_mut().ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let ops = serde_json::json!([
            {
                "op": "insert",
                "table": "Interface",
                "row": { "name": &name, "type": "system" },
                "uuid-name": "new_iface"
            },
            {
                "op": "insert",
                "table": "Port",
                "row": {
                    "name": &name,
                    "interfaces": ["set", [["named-uuid", "new_iface"]]]
                },
                "uuid-name": "new_port"
            },
            {
                "op": "mutate",
                "table": "Bridge",
                "where": [["name", "==", &bridge]],
                "mutations": [["ports", "insert", ["named-uuid", "new_port"]]]
            },
        ]);

        match client.transact(ops).await {
            Ok(_) => Ok(Response::new(PortResponse {
                name,
                bridge,
                success: true,
                message: "Port added".to_string(),
            })),
            Err(e) => Ok(Response::new(PortResponse {
                name,
                bridge,
                success: false,
                message: format!("Failed: {}", e),
            })),
        }
    }

    async fn list_ports(
        &self,
        request: Request<PortsRequest>,
    ) -> Result<Response<PortsResponse>, Status> {
        let bridge = request.into_inner().bridge;
        let mut guard = self.ovsdb_client().await?;
        let client = guard.as_mut().ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        let ops = serde_json::json!([{
            "op": "select",
            "table": "Bridge",
            "where": [["name", "==", &bridge]],
            "columns": ["ports"]
        }]);

        match client.transact(ops).await {
            Ok(result) => {
                let mut ports = Vec::new();
                if let Some(rows) = result.get("rows").and_then(|r| r.as_array()) {
                    if let Some(first) = rows.first() {
                        if let Some(port_set) = first.get("ports").and_then(|p| p.as_array()) {
                            for item in port_set.iter().skip(1) {
                                if let Some(uuid_arr) = item.as_array() {
                                    if uuid_arr.len() == 2 && uuid_arr[0] == "uuid" {
                                        if let Some(uuid) = uuid_arr[1].as_str() {
                                            let name_ops = serde_json::json!([{
                                                "op": "select",
                                                "table": "Port",
                                                "where": [["_uuid", "==", ["uuid", uuid]]],
                                                "columns": ["name"]
                                            }]);
                                            if let Ok(name_result) = client.transact(name_ops).await {
                                                if let Some(name_rows) = name_result.get("rows").and_then(|r| r.as_array()) {
                                                    if let Some(name_row) = name_rows.first() {
                                                        if let Some(port_name) = name_row.get("name").and_then(|n| n.as_str()) {
                                                            ports.push(port_name.to_string());
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                let count = ports.len() as i32;
                Ok(Response::new(PortsResponse { bridge, ports, count }))
            }
            Err(e) => Err(Status::internal(format!("OVSDB query failed: {}", e))),
        }
    }

    async fn list_databases(
        &self,
        _request: Request<DatabaseRequest>,
    ) -> Result<Response<DatabaseResponse>, Status> {
        let mut guard = self.ovsdb_client().await?;
        let client = guard.as_mut().ok_or_else(|| Status::internal("OVSDB client unavailable"))?;

        match client.list_dbs().await {
            Ok(dbs) => {
                let count = dbs.len() as i32;
                Ok(Response::new(DatabaseResponse { databases: dbs, count }))
            }
            Err(e) => Err(Status::internal(format!("OVSDB query failed: {}", e))),
        }
    }

    async fn get_status(
        &self,
        _request: Request<StatusRequest>,
    ) -> Result<Response<StatusResponse>, Status> {
        let connected = self.state.get_ovsdb().await.is_ok();
        Ok(Response::new(StatusResponse {
            connected,
            version: env!("CARGO_PKG_VERSION").to_string(),
            message: if connected {
                "Daemon connected to OVSDB".to_string()
            } else {
                "Daemon not connected to OVSDB".to_string()
            },
        }))
    }
}

/// Run the gRPC server
pub async fn run_grpc_server(addr: SocketAddr, state: DaemonState) -> Result<()> {
    info!("gRPC server starting on {}", addr);

    let service = OvsdbServiceImpl::new(state);

    tonic::transport::Server::builder()
        .add_service(OvsdbServiceServer::new(service))
        .serve(addr)
        .await
        .map_err(|e| anyhow::anyhow!("gRPC server error: {}", e))?;

    Ok(())
}

//! Pure passthrough D-Bus interfaces for the op-openvswitch-daemon.
//!
//! TWO separate object paths (locked design):
//! - `/org/opdbus/rovs/jsonrpc`  → interface `org.opdbus.rovs.jsonrpc`
//! - `/org/opdbus/rovs/openflow` → interface `org.opdbus.rovs.openflow`
//!
//! The daemon knows NOTHING about bridges, ports, or containers.  It only
//! proxies raw `rovs-jsonrpc` / `rovs-openflow` primitives over D-Bus.
//! Business logic lives in the consuming plugins.

use anyhow::{Context, Result};
use rovs_ovsdb::Client;
use rovs_transport::Address;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::Mutex;
use tracing::{debug, info};
use zbus::interface;

// ── Shared daemon state ───────────────────────────────────────────────────────

/// Global state shared by both D-Bus objects.
#[derive(Clone)]
pub struct DaemonState {
    /// OVSDB JSON-RPC client (rovs_ovsdb).  Lazily initialised on first call.
    pub ovsdb: Arc<Mutex<Option<Client>>>,
    /// OVS Unix-domain socket path.
    pub socket_path: String,
    /// OpenFlow connections: conn_id → VConn.
    pub of_conns: Arc<Mutex<HashMap<u64, rovs_openflow::VConn>>>,
    /// Monotonic connection handle allocator.
    pub next_of_id: Arc<Mutex<u64>>,
}

impl DaemonState {
    pub fn new(socket_path: String) -> Self {
        Self {
            ovsdb: Arc::new(Mutex::new(None)),
            socket_path,
            of_conns: Arc::new(Mutex::new(HashMap::new())),
            next_of_id: Arc::new(Mutex::new(1)),
        }
    }

    /// Get or create the persistent OVSDB client.
    pub async fn get_ovsdb(&self) -> Result<tokio::sync::MutexGuard<'_, Option<Client>>> {
        let mut guard = self.ovsdb.lock().await;
        if guard.is_none() {
            let client = Client::connect(&format!("unix:{}", self.socket_path))
                .await
                .with_context(|| format!("connect to OVSDB at {}", self.socket_path))?;
            info!("OVSDB client connected to {}", self.socket_path);
            *guard = Some(client);
        }
        Ok(guard)
    }

    /// Allocate a new OpenFlow connection handle id.
    pub async fn alloc_of_id(&self) -> u64 {
        let mut n = self.next_of_id.lock().await;
        let id = *n;
        *n += 1;
        id
    }
}

// ── JSON-RPC object (/org/opdbus/rovs/jsonrpc) ──────────────────────────────

/// D-Bus service proxying raw `rovs-jsonrpc` + `rovs-ovsdb` primitives.
pub struct JsonRpcService {
    state: DaemonState,
}

impl JsonRpcService {
    pub fn new(state: DaemonState) -> Self {
        Self { state }
    }
}

