//! op-openvswitch-daemon — D-Bus hypervisor for rovs crate family
//!
//! Pure pass-through proxy:
//! - /org/opdbus/rovs/jsonrpc  → OVSDB JSON-RPC (rovs-jsonrpc)
//! - /org/opdbus/rovs/openflow → OpenFlow (rovs-openflow)
//!
//! AGENTS.md §4: D-Bus first, D-Bus only. No CLI wrappers. No OvsdbClient.

use anyhow::{Context, Result};
use rovs_jsonrpc::Connection as JsonRpcConnection;
use rovs_openflow::VConn;
use rovs_transport::{Stream, reconnect::Reconnect};
use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::Arc;
use tokio::net::TcpListener;
use tokio::sync::{Mutex, RwLock};
use tracing::{info, warn, error};
use zbus::{connection, interface, Connection};

// ── Configuration ────────────────────────────────────────────────────────────

